import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {createServer} from '/Users/alejandrotreny/Documents/ChatGPT/Villa-Treny/node_modules/vite/dist/node/index.js';
const root='/Users/alejandrotreny/Documents/ChatGPT/Villa-Treny';
let requests=0;globalThis.fetch=()=>{requests++;throw Error('Offline only');};
const sha=x=>createHash('sha256').update(typeof x==='string'?x:JSON.stringify(x)).digest('hex');
const server=await createServer({root,configFile:false,appType:'custom',logLevel:'silent',server:{middlewareMode:true,hmr:false,watch:null},optimizeDeps:{noDiscovery:true,include:[]},plugins:[{name:'isolated-worker-wasm',enforce:'pre',async load(id){if(id.endsWith('tiktoken_bg.wasm'))return `export default new WebAssembly.Module(Uint8Array.from(${JSON.stringify([...await readFile(id)])}));`;}}]});
try {
 const core=Object.assign({},...await Promise.all(['/src/lib/habitat/society/index.ts','/src/lib/habitat/engine/state.ts','/src/lib/habitat/residents.ts','/workers/habitat-runtime/src/society-protocol.ts','/workers/habitat-runtime/src/society-scheduler.ts','/workers/habitat-runtime/src/providers/groq-tokenizer.ts','/workers/habitat-runtime/src/providers/groq-token-estimate.ts','/workers/habitat-runtime/src/providers/workers-ai.ts','/workers/habitat-runtime/src/providers/shared.ts'].map(p=>server.ssrLoadModule(p))));
 const world=core.genesisState(91),state=core.createSocietyState(world,1000),rows=[];
 async function measure(job){const parts=[job.prompt.system,job.prompt.user,JSON.stringify(job.outputContract.jsonSchema)],tokens=await core.tokenizeGroqOrdinary(parts);const cfPayload=JSON.stringify(core.workersAIInput(job,'@cf/openai/gpt-oss-120b'));return {ordinaryTokens:tokens?Object.fromEntries(['system','user','schema'].map((k,i)=>[k,tokens[i].length])):null,groqMaximum:await core.estimateGroqInputTokens(job)+job.maxOutputTokens,outputMaximum:job.maxOutputTokens,framingMargin:tokens?128:null,utf8Bytes:Object.fromEntries(['system','user','schema'].map((k,i)=>[k,Buffer.byteLength(parts[i])])),cfPayloadBytes:Buffer.byteLength(cfPayload),cfNeuronMaximum:core.estimateWorkersAINeurons('@cf/openai/gpt-oss-120b',core.estimateTokens(cfPayload),job.maxOutputTokens),jobHash:sha(job)};}
 const prepare=(s,w,actor,sequence,nowMs,protocolVersion=6)=>core.prepareSocietyJob({state:s,world:w,actor,nowMs,sequence,generation:0,worldRevision:0,habitatId:'offline-records-protocol6-measurement',protocolVersion});
 for(const{id:actor} of core.RESIDENTS){const p4=prepare(state,world,actor,1,2000,4),p6=prepare(state,world,actor,1,2000);rows.push({group:'initial',actor,p4:await measure(p4.job),p6:await measure(p6.job)});}
 const project={mode:'replace',goal:'Write a stores proposal.',why:'I want an exact text to discuss.',visibility:'private',steps:[]};
 let s=state,w=world;
 const first=prepare(s,w,'A',1,2000);
 const drafted=core.applySocietyProtocol(6,s,w,first.turn,{project,message:{to:'B',text:'Bex, would you review this exact proposal?'},record:{kind:'draft',title:'Stores proposal',text:'I propose comparing the stores register together, then recording any disagreements as claims.',refs:['world:100:1'],parent:null,audience:'B',publish:false}},{nowMs:2001,generation:0});assert.equal(drafted.ok,true,drafted.code);s=drafted.state;w=drafted.world;
 const d=s.records.drafts.at(-1),reply=prepare(s,w,'B',2,3000);rows.push({group:'shared-exact-draft',actor:'B',p4:await measure(prepare(s,w,'B',2,3000,4).job),p6:await measure(reply.job)});
 const offered=core.applySocietyProtocol(6,s,w,reply.turn,{project,message:{to:'A',text:'May I commission publication of this exact revision for one cell?'},record:{kind:'commission',draftId:d.id,contentHash:d.contentHash,counterpart:'A',cells:1,dueInWatches:2,audience:'B',visibility:'private'}},{nowMs:3001,generation:0});assert.equal(offered.ok,true,offered.code);s=offered.state;w=offered.world;
 const accept=prepare(s,w,'A',3,4000);rows.push({group:'incoming-commission',actor:'A',p4:await measure(prepare(s,w,'A',3,4000,4).job),p6:await measure(accept.job)});
 const accepted=core.applySocietyProtocol(6,s,w,accept.turn,{message:{to:'B',text:'I accept this exact publication commission.'},record:{kind:'accept',offerId:s.records.offers.at(-1).id}},{nowMs:4001,generation:0});assert.equal(accepted.ok,true,accepted.code);s=accepted.state;w=accepted.world;
 const follow=prepare(s,w,'A',4,5000);rows.push({group:'accepted-commission-review',actor:'A',p4:await measure(prepare(s,w,'A',4,5000,4).job),p6:await measure(follow.job)});
 const maxState=core.createSocietyState(world,1000);let ms=maxState,mw=world,seq=1;
 const fullText='A proposed comparison should record disagreement without inventing a corrected total. '.repeat(8);
 for(const [actor,to] of [['B','A'],['C','A'],['A','D']]){const title=actor+' record';const text=fullText.slice(0,600-Buffer.byteLength(title));assert.equal(Buffer.byteLength(title+text),600);const turn=prepare(ms,mw,actor,seq,2000+seq*1000);const out=core.applySocietyProtocol(6,ms,mw,turn.turn,{project,message:{to,text:'Here is a proposal for you to inspect.',close:true},record:{kind:'draft',title,text,refs:['world:100:1'],parent:null,audience:actor==='A'?'private':'A',publish:false}},{nowMs:2001+seq*1000,generation:0});assert.equal(out.ok,true,out.code);ms=out.state;mw=out.world;seq++;}
 for(const actor of ['B','C']){const draft=ms.records.drafts.find(d=>d.author===actor),job=prepare(ms,mw,actor,seq,2000+seq*1000);const out=core.applySocietyProtocol(6,ms,mw,job.turn,{record:{kind:'commission',draftId:draft.id,contentHash:draft.contentHash,counterpart:'A',cells:1,dueInWatches:2,audience:'A',visibility:'private'}},{nowMs:2001+seq*1000,generation:0});assert.equal(out.ok,true,out.code);ms=out.state;mw=out.world;seq++;}
 const maximum=prepare(ms,mw,'A',seq,2000+seq*1000);const maximumContext=JSON.parse(maximum.turn.prompt.slice(maximum.turn.prompt.lastIndexOf('\n{')+1));assert.equal(maximumContext.records.drafts.length,3);assert.equal(maximumContext.records.offers.length,2);assert.ok(maximumContext.records.drafts.every(d=>Buffer.byteLength(d.title+d.text)===600));rows.push({group:'three-full-drafts-two-incoming-commissions',actor:'A',exactDraftBytes:[600,600,600],p4:await measure(prepare(ms,mw,'A',seq,2000+seq*1000,4).job),p6:await measure(maximum.job)});
 const result={scope:'Offline synthetic P6 provider components. No remote inference, no production state. Exact ordinary tokens plus provisional framing and full output maximum; CF maximum uses conservative bytes.',requests,rows};await writeFile('/tmp/villa-records-p6-measurement.json',JSON.stringify(result,null,2));console.log(JSON.stringify({requests,initialMax:Math.max(...rows.slice(0,25).map(r=>r.p6.groqMaximum)),rows:rows.slice(25)}));
}finally{await server.close();}

